scripts.sum_squared_digits:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        # Calculate sum of squared digits
        digits = [int(d) for d in str(n)]
        n = sum(d**2 for d in digits)

    return float(n)

scripts.collatz:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1

    return float(n)

scripts.reverse_and_add:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        # Reverse the digits
        reversed_n = int(str(n)[::-1])
        # Add to original
        n = n + reversed_n

    return float(n)

scripts.running_total_reset:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    threshold = inputs['T']

    total = 0
    for val in values:
        total += val
        if total > threshold:
            total = 0

    return float(total)

